37	  // Bloqueia uma mesa livre (reserva, manutenção...) — fica indisponível pro garçom
38	  // até ser desbloqueada, sem precisar de comanda aberta nela.
39	  async bloquearMesa(mesaId: number, restaurantId: number) {
40	    const { data: mesa } = await this.supabase.client
41	      .from('mesas').select('id, status').eq('id', mesaId).eq('restaurant_id', restaurantId).maybeSingle();
42	    if (!mesa) throw new NotFoundException('Mesa não encontrada');
43	    if (mesa.status !== 'livre') throw new BadRequestException('Só é possível bloquear uma mesa livre');
44	
45	    const { error } = await this.supabase.client.from('mesas').update({ status: 'bloqueada' }).eq('id', mesaId);
46	    if (error) throw error;
47	    return { ok: true };
48	  }
