51	    const { data: mesa } = await this.supabase.client
52	      .from('mesas').select('id, status').eq('id', mesaId).eq('restaurant_id', restaurantId).maybeSingle();
53	    if (!mesa) throw new NotFoundException('Mesa não encontrada');
54	    if (mesa.status !== 'bloqueada') throw new BadRequestException('Mesa não está bloqueada');
