        printReciboCliente(
          res, carrinho.map((i) => ({ product_name: i.name, quantity: i.quantity, unit_price: i.price })),
          { subtotal, desconto, acrescimo, taxaCartao: taxaCartaoValor, total, formaPagamento: forma, trocoDado: Math.max(troco ?? 0, 0) },
        );
      }
      onVendida();
    } catch (err) {
      setErro(err.message ?? 'Não foi possível concluir a venda.');
    } finally {
      setSalvando(false);
    }
  };

