                className="bg-white border border-[#E4E4E7] rounded-xl p-2.5 text-left active:scale-[0.98] transition-transform disabled:opacity-50">
                <div className="w-full aspect-square rounded-lg overflow-hidden bg-[#F4F4F5] mb-2">
                  {p.image_url
                    ? <img src={p.image_url} alt="" className="w-full h-full object-cover" />
